def parse_monto(texto: str):
    raw = texto
    limpio = texto.strip()
    if limpio == "":
        return False, None, f"ERROR en 'monto': valor vacío (raw={raw!r})"
    try:
        monto = Decimal(limpio).quantize(Decimal("0.01"), rounding=ROUND_HALF_EVEN)
        return True, monto, None
    except InvalidOperation:
        return False, None, f"ERROR en 'monto': no se pudo convertir {raw!r} a Decimal"

def parse_nombres(valor: str) -> dict:
    errors = []
    clean = valor.strip()
    if clean == "":
        errors.append(f"ERROR en 'nombres': vacío (raw={valor!r})")
        clean = None
    return {"nombres_raw": valor, "nombres": clean, "errors": errors}
